// Teams: how the script knows that a feed's name for a team is the game's team.
//
// Each league has a closed list of teams (src/teams/, generated by capture/teams.ts). A team is
// one key and every spelling the program accepts for it. A spelling is there only because a seat's
// own list carries it and a reviewed identity joins it to that one team: the team's own name on
// seat 1's list, or a hand join with its reason (capture/joins.json). Nothing shortens a name to
// make it match, and no spelling is on two teams. A name resolves to a team when its comparison
// form equals one of that team's spellings; anything else resolves to nothing, and a record whose
// two teams do not both resolve is not the game. The spellings of the four seats share one list
// per league: a spelling one seat writes for a team cannot mean another team at another seat,
// because no spelling is on two teams.

import { TEAMS } from "./teams/index";

export interface Team {
	readonly key: string;
	readonly names: readonly string[];
}

/**
 * The comparison form of a name: lower case, accents and punctuation dropped, "&" read as "and",
 * runs of spaces collapsed. "St. Mary's (CA)" and "st marys ca" compare equal.
 */
export function normalise(raw: string): string {
	return raw
		.normalize("NFKD")
		.replace(/[̀-ͯ]/g, "")
		.toLowerCase()
		.replace(/&/g, " and ")
		.replace(/['’.]/g, "")
		.replace(/[^a-z0-9]+/g, " ")
		.trim();
}

type Index = ReadonlyMap<string, string | null>; // normalised spelling -> team key (null: two teams)

const INDEXES = new Map<string, Index>();

function indexFor(league: string): Index | null {
	const cached = INDEXES.get(league);
	if (cached) return cached;
	if (!Object.prototype.hasOwnProperty.call(TEAMS, league)) return null;
	const teams = TEAMS[league];
	const index = new Map<string, string | null>();
	for (const team of teams) {
		for (const name of team.names) {
			const n = normalise(name);
			if (n === "") continue;
			const prior = index.get(n);
			if (prior === undefined) index.set(n, team.key);
			else if (prior !== team.key) index.set(n, null);
		}
	}
	INDEXES.set(league, index);
	return index;
}

/** The team a name means in a league, or null when it means none or more than one. */
export function resolveTeam(league: string, name: unknown): string | null {
	if (typeof name !== "string") return null;
	const index = indexFor(league);
	if (!index) return null;
	const hit = index.get(normalise(name));
	return hit === undefined ? null : hit;
}
